CREATE TABLE executions(id BIGSERIAL PRIMARY KEY,type VARCHAR(20) NOT NULL,workflow_id BIGINT,command_definition_id BIGINT REFERENCES command_definitions(id),started_by BIGINT NOT NULL REFERENCES users(id),mode VARCHAR(20) NOT NULL,concurrency INT NOT NULL DEFAULT 1,failure_policy VARCHAR(40) NOT NULL,status VARCHAR(30) NOT NULL,started_at TIMESTAMPTZ,finished_at TIMESTAMPTZ);CREATE TABLE machine_runs(id BIGSERIAL PRIMARY KEY,execution_id BIGINT NOT NULL REFERENCES executions(id),machine_id BIGINT NOT NULL REFERENCES machines(id),credential_id BIGINT REFERENCES credentials(id),status VARCHAR(30) NOT NULL,failure_reason TEXT,started_at TIMESTAMPTZ,finished_at TIMESTAMPTZ);CREATE TABLE step_runs(id BIGSERIAL PRIMARY KEY,machine_run_id BIGINT NOT NULL REFERENCES machine_runs(id),workflow_step_id BIGINT,status VARCHAR(30) NOT NULL,original_command TEXT,resolved_command TEXT,resolved_parameters JSONB,manually_edited BOOLEAN NOT NULL DEFAULT false,stdout TEXT,stderr TEXT,exit_code INT,failure_reason TEXT,attempt_number INT NOT NULL DEFAULT 1,retry_of_step_run_id BIGINT REFERENCES step_runs(id),started_at TIMESTAMPTZ,finished_at TIMESTAMPTZ);CREATE TABLE approval_requests(id BIGSERIAL PRIMARY KEY,step_run_id BIGINT NOT NULL REFERENCES step_runs(id),status VARCHAR(30) NOT NULL,requested_at TIMESTAMPTZ NOT NULL DEFAULT now(),approved_by BIGINT REFERENCES users(id),decided_at TIMESTAMPTZ);CREATE INDEX idx_executions_user ON executions(started_by,started_at);CREATE INDEX idx_machine_runs_execution ON machine_runs(execution_id);CREATE INDEX idx_step_runs_machine ON step_runs(machine_run_id);